from itertools import permutations
def solve(faces, views):
    # views: list of (top, left, right) seen at a front corner; left->right is clockwise around top viewed from above
    # a cube labelling: opposite pairs; enumerate all labellings as positions
    # positions: U,D,F,B,L,R ; corner view (top,left,right) valid if exists orientation.
    import itertools
    # adjacency cycles around each face in clockwise order when viewed from outside that face
    cyc={'U':['F','L','B','R'],'D':['F','R','B','L'],'F':['U','R','D','L'],'B':['U','L','D','R'],'L':['U','F','D','B'],'R':['U','B','D','F']}
    res=set()
    for p in permutations(faces):
        lab=dict(zip('UDFBLR',p))
        pos={v:k for k,v in lab.items()}
        ok=True
        for t,l,r in views:
            c=cyc[pos[t]]
            if pos[l] not in c or pos[r] not in c: ok=False;break
            # viewed from above with our corner at front: left face then right face appear clockwise? left->right is counter-clockwise from above
            i=c.index(pos[l])
            if c[(i-1)%4]!=pos[r]: ok=False;break
        if ok: res.add(frozenset(frozenset((lab[a],lab[b])) for a,b in ('UD','FB','LR')))
    return res

sols=solve('XTSMRO',[('X','T','S'),('X','M','R')])
opp=set()
for s in sols:
    for pr in s:
        if 'R' in pr: opp|=set(pr)-{'R'}
assert opp=={'S'}
for v in ('M','O','T'): assert v not in opp

# net cells (col,row): Bat(1,0) Ball(0,1) Net(1,1) Stick(1,2) Goal(1,3) Field(2,3)
net={(1,0):'Bat',(0,1):'Ball',(1,1):'Net',(1,2):'Stick',(1,3):'Goal',(2,3):'Field'}
# roll a cube: state maps face-direction -> normal vector; start with Net on bottom
def roll(o,d):
    # o: dict name->normal (x,y,z); rolling in +x/-x/+y/-y rotates normals
    dx,dy=d; r={}
    for k,(x,y,z) in o.items():
        if dx==1: r[k]=(-z,y,x)
        elif dx==-1: r[k]=(z,y,-x)
        elif dy==1: r[k]=(x,-z,y)
        else: r[k]=(x,z,-y)
    return r
bottom={}
start=(1,1); seen={start}; stack=[(start,{'_':(0,0,-1)})]
# track which world normal is the face touching the ground: we instead track position of the unfolded face
pos={start:(0,0,-1)}
def rot(v,d):
    x,y,z=v; dx,dy=d
    if dx==1: return (-z,y,x)
    if dx==-1: return (z,y,-x)
    if dy==1: return (x,-z,y)
    return (x,z,-y)
# face at neighbour cell = the face that becomes bottom after rolling; compute in cube frame by inverse
from collections import deque
frame={start:[(1,0,0),(0,1,0),(0,0,1)]}
normal={start:(0,0,-1)}
q=deque([start])
def inv_apply(fr,v):
    # express world vector v in cube coordinates given frame fr (world images of cube axes)
    return tuple(sum(fr[i][j]*v[j] for j in range(3)) for i in range(3))
while q:
    c=q.popleft()
    for d in ((1,0),(-1,0),(0,1),(0,-1)):
        n=(c[0]+d[0],c[1]+d[1])
        if n in net and n not in frame:
            # rolling cube towards direction d: world rotation R; new frame = R(frame)
            fr=[rot(a,d) for a in frame[c]]
            frame[n]=fr
            # bottom face in cube coords: world (0,0,-1) expressed in cube coords
            q.append(n)
cubeface={net[c]:inv_apply(frame[c],(0,0,-1)) for c in net}
assert len(set(cubeface.values()))==6
def opposite(w):
    v=cubeface[w]; t=tuple(-a for a in v)
    return [k for k,u in cubeface.items() if u==t][0]
