from fractions import Fraction as F
import operator as o
ops={'+':o.add,'-':o.sub,'÷':o.truediv}
def ev(s):
    n=[F(8),F(27),F(9),F(6),F(5)]
    # standard BODMAS: handle ÷ first
    nums=[n[0]];pend=[]
    for op,x in zip(s,n[1:]):
        if op=='÷': nums[-1]=nums[-1]/x
        else: pend.append(op); nums.append(x)
    r=nums[0]
    for op,x in zip(pend,nums[1:]): r=ops[op](r,x)
    return r
